import{a0 as s,I as l,g as c,d as t,k as d,V as h,Y as u,j as p}from"./chunks/framework.CjoWWfVe.js";const b=JSON.parse('{"title":"License & Privacy Policy","description":"End-User License Agreement (EULA) and Privacy Policy for OmniCraft ERP.","frontmatter":{"title":"License & Privacy Policy","description":"End-User License Agreement (EULA) and Privacy Policy for OmniCraft ERP.","order":20,"eula_version":20260905,"eula_date":"2026-09-05"},"headers":[],"relativePath":"docs/terms.md","filePath":"docs/terms.md"}'),m={name:"docs/terms.md"},v=Object.assign(m,{setup(f){const{frontmatter:i}=s(),r=a=>{if(!a)return"";const[e,n,o]=a.split("-");return`${["January","February","March","April","May","June","July","August","September","October","November","December"][parseInt(n)-1]} ${parseInt(o)}, ${e}`};return(a,e)=>(l(),c("div",null,[e[0]||(e[0]=t("h1",{id:"⚖️-license-agreement-privacy-policy",tabindex:"-1"},[d("⚖️ License Agreement & Privacy Policy "),t("a",{class:"header-anchor",href:"#⚖️-license-agreement-privacy-policy","aria-label":'Permalink to "⚖️ License Agreement & Privacy Policy"'},"​")],-1)),t("p",null,[t("em",null,"Effective Date: "+h(r(u(i).eula_date)),1)]),e[1]||(e[1]=p('<p>This document is an official offer (public agreement) and constitutes a single legal agreement between you (hereinafter — the &quot;User&quot;) and the Developer (hereinafter — the &quot;Licensor&quot;) regarding the use of the &quot;OmniCraft ERP&quot; software (hereinafter — the &quot;Software&quot;) and the official website.</p><p>By installing, copying, downloading, or otherwise using the Software, the User unconditionally agrees to all the terms of this document. If you do not agree to the terms, you must cease using the Software and delete it from your devices.</p><hr><h2 id="part-1-end-user-license-agreement-eula" tabindex="-1">PART 1. END-USER LICENSE AGREEMENT (EULA) <a class="header-anchor" href="#part-1-end-user-license-agreement-eula" aria-label="Permalink to &quot;PART 1. END-USER LICENSE AGREEMENT (EULA)&quot;">​</a></h2><h3 id="_1-1-subject-of-the-agreement-and-operating-principle" tabindex="-1">1.1. Subject of the Agreement and Operating Principle <a class="header-anchor" href="#_1-1-subject-of-the-agreement-and-operating-principle" aria-label="Permalink to &quot;1.1. Subject of the Agreement and Operating Principle&quot;">​</a></h3><p>The Licensor grants the User a personal, non-exclusive, non-transferable right to use the Software according to its functional purpose worldwide for the entire duration of the exclusive right. The Software is developed based on a <strong>Local-First</strong> architecture. This means that the Software operates autonomously on the User&#39;s local device. All user data, including databases, financial transactions, and inventory, are created, processed, and stored exclusively on the User&#39;s local hard drive.</p><h3 id="_1-2-license-types-and-tiers" tabindex="-1">1.2. License Types and Tiers <a class="header-anchor" href="#_1-2-license-types-and-tiers" aria-label="Permalink to &quot;1.2. License Types and Tiers&quot;">​</a></h3><p>The Software provides the following access levels:</p><ol><li><strong>Free (Trial Version):</strong> Provided free of charge without time limits. Includes the full functionality of the Software with a technical limitation: after completing 20 (twenty) sales transactions (receipts), the Software switches to &quot;Read-Only&quot; mode for production and trading operations.</li><li><strong>&quot;Standard&quot; License (subscription or perpetual):</strong> Activated via a unique license key purchased by the User. Removes limitations on the number of operations.</li><li><strong>&quot;PRO&quot; License (perpetual):</strong> Purchased as an extension for the Standard license. Unlocks access to Multi-Workspaces and the global &quot;My Capital&quot; tab.</li><li><strong>Specialized Modules:</strong> Purchased as one-time add-ons tailored to specific crafts.</li></ol><p>The license key is technically bound to the User&#39;s unique hardware identifier (HWID). One commercial license can be bound to no more than 5 (five) devices simultaneously. The User can independently edit and reset the list of bound devices via the license management form on the official website. Current license prices are fixed on the <a href="/docs/buy-license">Purchasing a License</a> page.</p><h3 id="_1-3-usage-restrictions" tabindex="-1">1.3. Usage Restrictions <a class="header-anchor" href="#_1-3-usage-restrictions" aria-label="Permalink to &quot;1.3. Usage Restrictions&quot;">​</a></h3><p>The User is strictly prohibited from:</p><ul><li>Decompiling, disassembling, modifying, or attempting to extract the source code of the Software.</li><li>Renting, selling, sublicensing, or transferring activation keys to third parties.</li><li>Using the Software for actions contrary to applicable law.</li><li>Attempting to bypass the technical limitations of the Free version by any means.</li></ul><h3 id="_1-4-limitation-of-liability-and-disclaimer-of-warranties" tabindex="-1">1.4. Limitation of Liability and Disclaimer of Warranties <a class="header-anchor" href="#_1-4-limitation-of-liability-and-disclaimer-of-warranties" aria-label="Permalink to &quot;1.4. Limitation of Liability and Disclaimer of Warranties&quot;">​</a></h3><p><strong>The Software is provided &quot;as is&quot;. The Licensor makes no express or implied warranties that the Software will meet the User&#39;s requirements or that it will operate uninterrupted, without failures or errors.</strong></p><p>THE USER UNDERSTANDS AND AGREES THAT UNDER NO CIRCUMSTANCES SHALL THE LICENSOR BE LIABLE FOR:</p><ol><li>Loss, distortion, or corruption of the User&#39;s local databases resulting from power failures, hard drive crashes, viruses, or incorrect actions by the User.</li><li>Any direct or indirect damages, lost profits, or business interruption arising from the use or inability to use the Software.</li></ol><p><strong>Backups:</strong> The User acknowledges that the entire responsibility for the safety of commercial information rests solely with them. The User agrees to independently and regularly back up their data using the Software&#39;s built-in tools (export to .db and .zip formats).</p><p><strong>Artificial Intelligence (AI) Integration:</strong> The Software provides integration functionality with third-party artificial intelligence services under the Bring Your Own Key (BYOK) model. The User is solely responsible for compliance with the terms of third-party services and payment for their usage. All information, calculations, and materials generated using AI technologies are provided on an &quot;AS IS&quot; basis and are for informational purposes only. The User is obligated to independently validate any operational, economic, and financial data prior to its practical application.</p><h3 id="_1-5-returns-and-cancellations" tabindex="-1">1.5. Returns and Cancellations <a class="header-anchor" href="#_1-5-returns-and-cancellations" aria-label="Permalink to &quot;1.5. Returns and Cancellations&quot;">​</a></h3><ul><li><strong>Cancellation before receiving the digital product (before service rendering):</strong> The Buyer has the right to cancel the purchase and request a refund at any time before the actual receipt (automatic generation and sending to e-mail) of the license activation key.</li><li><strong>Step-by-step refund procedure:</strong><ol><li>To process a refund, the User must send a free-form request via any method specified on the <a href="/docs/contacts">Contacts &amp; Legal Details</a> page. The request must include the payment date and time, HWID, the email specified during purchase, and the amount.</li><li>The Licensor processes the request within <strong>3 business days</strong>.</li><li>Upon confirmation, the refund is made in full to the same bank card or account from which the payment was made.</li><li>The actual arrival of funds to the User&#39;s account depends on their issuing bank and usually takes <strong>1 to 5 business days</strong> (rarely up to 30 days according to payment system rules).</li><li><strong>Important:</strong> Refunds are issued in full without deducting any payment service or bank commissions (the User receives exactly the amount paid).</li></ol></li><li><strong>Cancellation after receiving the digital product:</strong> The provision of the non-exclusive right to the User is considered fully executed (service rendered) at the moment the unique license activation key is automatically generated and sent to the User&#39;s e-mail. In accordance with applicable laws, refunds for a digital product of proper quality are not provided after its transfer to the User. Before purchasing a commercial license, the User is provided with a free trial version of the Software without time limits to fully evaluate its features and consumer properties. In case of any technical problems with key activation or Software stability, the Licensor commits to promptly resolving the issue or replacing the key.</li></ul><hr><h2 id="part-2-privacy-policy" tabindex="-1">PART 2. PRIVACY POLICY <a class="header-anchor" href="#part-2-privacy-policy" aria-label="Permalink to &quot;PART 2. PRIVACY POLICY&quot;">​</a></h2><h3 id="_2-1-no-collection-of-personal-data" tabindex="-1">2.1. No Collection of Personal Data <a class="header-anchor" href="#_2-1-no-collection-of-personal-data" aria-label="Permalink to &quot;2.1. No Collection of Personal Data&quot;">​</a></h3><p>Due to the Local-First architecture, the Licensor <strong>has no access</strong> to the User&#39;s databases. The Licensor does not collect, process, or store the personal data of the User&#39;s clients, supplier lists, trade secrets, income data, or account balances.</p><h3 id="_2-2-automatically-collected-technical-information-telemetry" tabindex="-1">2.2. Automatically Collected Technical Information (Telemetry) <a class="header-anchor" href="#_2-2-automatically-collected-technical-information-telemetry" aria-label="Permalink to &quot;2.2. Automatically Collected Technical Information (Telemetry)&quot;">​</a></h3><p>To ensure the operation of the licensing system and improve the Software&#39;s quality, the Licensor may collect strictly anonymized technical telemetry:</p><ul><li><strong>HWID (Hardware ID):</strong> An anonymized cryptographic hash of hardware parameters used solely for verifying license binding and anti-piracy protection.</li><li><strong>Technical Metrics:</strong> Interface language, OS version, Software version, and sales transaction counter.</li><li><strong>Crash Reports:</strong> In the event of a critical error, the Software sends an error log (traceback) where local PC paths are masked.</li></ul><p>If any of the collected technical information (e.g., IP address, HWID) is deemed personal data under applicable law, the Licensor processes it solely for the purpose of executing this Agreement (pursuant to Clause 5, Part 1, Article 6 of Federal Law No. 152-FZ &quot;On Personal Data&quot;).</p><h3 id="_2-3-processing-of-personal-data-during-checkout" tabindex="-1">2.3. Processing of Personal Data During Checkout <a class="header-anchor" href="#_2-3-processing-of-personal-data-during-checkout" aria-label="Permalink to &quot;2.3. Processing of Personal Data During Checkout&quot;">​</a></h3><ul><li>Upon purchasing and paying for a license through an authorized payment gateway (online payment processing), the User provides an email address (e-mail) and the HWID of the device.</li><li>By providing data, the User expresses consent to the processing of this information by the Licensor solely for the purpose of automatic generation, delivery, and technical support of the license token.</li><li><strong>To ensure privacy and minimize data collection, the email address (e-mail) is used by the Licensor solely to send the message with the license token at the exact moment of the transaction and is not saved or stored in databases on the Licensor&#39;s servers.</strong> Only the anonymized license token and the device&#39;s hashed fingerprint are stored in the Licensor&#39;s databases.</li><li>Collection and processing of this data are carried out in compliance with all necessary information security measures. The data is not transferred to third parties under any circumstances (except for the legal requirements of the authorities of the Russian Federation).</li></ul><h3 id="_2-4-consent-management-opt-out" tabindex="-1">2.4. Consent Management (Opt-Out) <a class="header-anchor" href="#_2-4-consent-management-opt-out" aria-label="Permalink to &quot;2.4. Consent Management (Opt-Out)&quot;">​</a></h3><p>The User has the right to withdraw their consent to the transmission of analytical telemetry and crash reports at any time by unchecking the corresponding option in the &quot;Global Settings&quot; of the Software.</p><h3 id="_2-5-web-resources-usage" tabindex="-1">2.5. Web Resources Usage <a class="header-anchor" href="#_2-5-web-resources-usage" aria-label="Permalink to &quot;2.5. Web Resources Usage&quot;">​</a></h3><p>When visiting <code>omnicraft-erp.com</code> or interacting with the Licensor&#39;s official billing servers (including the <code>nmurashkin.ru</code> domain), the web server may automatically collect standard connection logs (IP address, browser type, access time) solely for network security and DDoS protection purposes. The website does not use advertising or tracking third-party cookies.</p><h3 id="_2-6-local-and-session-browser-storage-usage-sessionstorage" tabindex="-1">2.6. Local and Session Browser Storage Usage (sessionStorage) <a class="header-anchor" href="#_2-6-local-and-session-browser-storage-usage-sessionstorage" aria-label="Permalink to &quot;2.6. Local and Session Browser Storage Usage (sessionStorage)&quot;">​</a></h3><p>The website uses local session browser storage (<code>sessionStorage</code>) strictly to maintain the technical functionality of the user cabinet and preserve authorization status during an active user session. Data is stored locally on the user&#39;s device. Stored information is not used for tracking or marketing purposes and is automatically erased by the browser when the tab or browser window is closed.</p><hr><h2 id="payment-delivery-returns" tabindex="-1">PART 3. PAYMENT, DELIVERY &amp; RETURNS <a class="header-anchor" href="#payment-delivery-returns" aria-label="Permalink to &quot;PART 3. PAYMENT, DELIVERY &amp; RETURNS {#payment-delivery-returns}&quot;">​</a></h2><h3 id="_3-1-product-description-and-properties" tabindex="-1">3.1. Product Description and Properties <a class="header-anchor" href="#_3-1-product-description-and-properties" aria-label="Permalink to &quot;3.1. Product Description and Properties&quot;">​</a></h3><p>The product is a non-exclusive right to use the software (digital license key). Product properties: activating the license key in OmniCraft ERP removes the basic technical restriction of the free version (the 20-receipt limit) and, depending on the selected plan, grants access to advanced features (unlimited sales, Multi-Workspaces, the &quot;My Capital&quot; module). The product is delivered exclusively in digital (electronic) form.</p><h3 id="_3-2-payment-conditions-and-methods" tabindex="-1">3.2. Payment Conditions and Methods <a class="header-anchor" href="#_3-2-payment-conditions-and-methods" aria-label="Permalink to &quot;3.2. Payment Conditions and Methods&quot;">​</a></h3><p>Payment is processed online via an authorized payment gateway (online payment processing), which fully complies with international security standards (PCI DSS). Accepted payment methods:</p><ul><li>Bank cards (MIR, Visa, Mastercard, UnionPay).</li><li>Fast Payment System (SBP).</li><li>Yandex Pay and other available electronic methods. All transmitted data is encrypted using the secure SSL protocol, ensuring absolute safety for your payment details.</li></ul><h3 id="_3-3-delivery-process-service-rendering" tabindex="-1">3.3. Delivery Process (Service Rendering) <a class="header-anchor" href="#_3-3-delivery-process-service-rendering" aria-label="Permalink to &quot;3.3. Delivery Process (Service Rendering)&quot;">​</a></h3><ul><li>Delivery of the digital product is processed automatically or manually by sending an email to the e-mail address provided by the Buyer during payment.</li><li>Execution time: automatic generation and dispatch of the key takes from 1 to 5 minutes from the moment of successful payment. During the setup of the automatic billing system, if payment is processed manually, the license key will be sent within 24 hours of payment confirmation.</li></ul><h3 id="_3-4-returns-and-order-cancellations" tabindex="-1">3.4. Returns and Order Cancellations <a class="header-anchor" href="#_3-4-returns-and-order-cancellations" aria-label="Permalink to &quot;3.4. Returns and Order Cancellations&quot;">​</a></h3><ul><li><strong>Cancellation before receiving the digital product (before service rendering):</strong> The Buyer has the right to cancel the purchase and request a refund at any time before the actual receipt (automatic generation and sending to e-mail) of the license activation key.</li><li><strong>Step-by-step refund procedure:</strong><ol><li>To process a refund, the User must send a free-form request via any method specified on the <a href="/docs/contacts">Contacts &amp; Legal Details</a> page. The request must include the payment date and time, HWID, the email specified during purchase, and the amount.</li><li>The Licensor processes the request within <strong>3 business days</strong>.</li><li>Upon confirmation, the refund is made in full to the same bank card or account from which the payment was made.</li><li>The actual arrival of funds to the User&#39;s account depends on their issuing bank and usually takes 1 to 5 business days.</li><li><strong>Important:</strong> Refunds are issued in full without deducting any payment service or bank commissions (the User receives exactly the amount paid).</li></ol></li><li><strong>Cancellation after receiving the digital product:</strong> The provision of the non-exclusive right to the User is considered fully executed (service rendered) at the moment the unique license activation key is automatically generated and sent to the User&#39;s e-mail. In accordance with applicable laws, refunds for a digital product of proper quality are not provided after its transfer to the User. Before purchasing a commercial license, the User is provided with a free trial version of the Software without time limits to fully evaluate its features and consumer properties. In case of any technical problems with key activation or Software stability, the Licensor commits to promptly resolving the issue or replacing the key.</li></ul><h2 id="part-4-final-provisions-and-details" tabindex="-1">PART 4. FINAL PROVISIONS AND DETAILS <a class="header-anchor" href="#part-4-final-provisions-and-details" aria-label="Permalink to &quot;PART 4. FINAL PROVISIONS AND DETAILS&quot;">​</a></h2><h3 id="_4-1-applicable-law-and-dispute-resolution" tabindex="-1">4.1. Applicable Law and Dispute Resolution <a class="header-anchor" href="#_4-1-applicable-law-and-dispute-resolution" aria-label="Permalink to &quot;4.1. Applicable Law and Dispute Resolution&quot;">​</a></h3><p>This Agreement is governed by and construed in accordance with the laws of the Russian Federation. All disputes and disagreements arising in connection with this Agreement shall be subject to mandatory pre-trial claim settlement. The period for considering a written claim is 30 (thirty) calendar days from the date of its receipt. If a dispute cannot be resolved through the pre-trial procedure, it shall be referred to the court at the Licensor&#39;s location.</p><h3 id="_4-2-force-majeure" tabindex="-1">4.2. Force Majeure <a class="header-anchor" href="#_4-2-force-majeure" aria-label="Permalink to &quot;4.2. Force Majeure&quot;">​</a></h3><p>The Parties shall be released from liability for partial or complete failure to perform their obligations under this Agreement if such failure is caused by force majeure events. Such circumstances include extraordinary and unavoidable events, including military actions, natural disasters, decisions of government authorities, large-scale failures in the Internet, failures of servers or cloud providers, as well as severe sudden illness or emergency hospitalization of the Licensor that objectively prevents the performance of obligations in a timely manner. The time for performing obligations under this Agreement shall be extended proportionally to the duration of such circumstances.</p><h3 id="_4-3-amendments" tabindex="-1">4.3. Amendments <a class="header-anchor" href="#_4-3-amendments" aria-label="Permalink to &quot;4.3. Amendments&quot;">​</a></h3><p>The Licensor reserves the right to unilaterally amend this Agreement. The new version becomes effective from the moment it is published on the official website of the Program. In the event of the User&#39;s disagreement with the amendments to the Agreement, the User must immediately cease all use of the Program and delete it from their devices. Continued use of the Program after the terms have been amended shall constitute consent to the new version of the Agreement.</p><h3 id="_4-4-language-of-the-agreement" tabindex="-1">4.4. Language of the Agreement <a class="header-anchor" href="#_4-4-language-of-the-agreement" aria-label="Permalink to &quot;4.4. Language of the Agreement&quot;">​</a></h3><p>This Agreement may be translated into other languages for the convenience of Users. In the event of any discrepancies, contradictions, or inconsistencies between the Russian version of this Agreement and its version in any other language, the Russian version shall always prevail, govern, and be final.</p><h3 id="_4-5-developer-licensor-details" tabindex="-1">4.5. Developer (Licensor) Details <a class="header-anchor" href="#_4-5-developer-licensor-details" aria-label="Permalink to &quot;4.5. Developer (Licensor) Details&quot;">​</a></h3><p>The copyright holder and Developer of the Software is: <strong>Nikolai Valerievich Murashkin</strong>, registered as self-employed (NPD tax regime in the Russian Federation). Detailed information about the developer, his workshop, and the project philosophy is available in the <a href="/docs/about">About the Developers</a> section.</p><ul><li><strong>Tax ID (INN):</strong> 232904256501</li><li><strong>Contact for official inquiries:</strong> The initial submission of legally significant communications, requests, pre-trial claims, and licensing issues must be made exclusively via the contacts specified on the <a href="/docs/contacts">contacts page</a>. Following the initial submission, further correspondence and exchange of documents may be conducted via email using the addresses from which the Licensor&#39;s responses are sent.</li></ul>',60))]))}});export{b as __pageData,v as default};
